export interface JobOptions<TPayload> {
  /** Names the job in logs and dashboards. */
  id: string;
  /**
   * The queue the job consumes. When given, it is the name senders
   * enqueue to; when absent, the job consumes the queue named by its id.
   */
  queue?: string;
  run: (payload: TPayload) => Promise<void>;
}

export interface Job<TPayload> {
  cancel(): void;
}

export declare function job<TPayload>(options: JobOptions<TPayload>): Job<TPayload>;

export declare const queues: {
  enqueue(queue: string, payload: unknown): Promise<void>;
};
